const omp_abi_depend_kind_t = omp_abi_depend_kind_e

struct __JL_Ctag_1
    in::Cuchar
    out::Cuchar
    mtx::Cuchar
    set::Cuchar
    unused::Cuchar
    all::Cuchar
end
function Base.getproperty(x::Ptr{__JL_Ctag_1}, f::Symbol)
    f === :in && return (Ptr{Cuchar}(x + 0), 0, 1)
    f === :out && return (Ptr{Cuchar}(x + 0), 1, 1)
    f === :mtx && return (Ptr{Cuchar}(x + 0), 2, 1)
    f === :set && return (Ptr{Cuchar}(x + 0), 3, 1)
    f === :unused && return (Ptr{Cuchar}(x + 0), 4, 3)
    f === :all && return (Ptr{Cuchar}(x + 0), 7, 1)
    return getfield(x, f)
end

function Base.getproperty(x::__JL_Ctag_1, f::Symbol)
    r = Ref{__JL_Ctag_1}(x)
    ptr = Base.unsafe_convert(Ptr{__JL_Ctag_1}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{__JL_Ctag_1}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end


struct omp_abi_depend_info
    data::NTuple{24, UInt8}
end

function Base.getproperty(x::Ptr{omp_abi_depend_info}, f::Symbol)
    f === :base_addr && return Ptr{Cptrdiff_t}(x + 0)
    f === :len && return Ptr{Csize_t}(x + 8)
    f === :flags && return Ptr{__JL_Ctag_1}(x + 16)
    return getfield(x, f)
end

function Base.getproperty(x::omp_abi_depend_info, f::Symbol)
    r = Ref{omp_abi_depend_info}(x)
    ptr = Base.unsafe_convert(Ptr{omp_abi_depend_info}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{omp_abi_depend_info}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::omp_abi_depend_info, private::Bool = false)
    (:base_addr, :len, :flags, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

